script:
const el = {};
const RED = "#c0392b", GREY = "#7b8a90";
const ARC = (x0, x1, yb, yc) => `M${x0} ${yb} C${x0} ${yc} ${x1} ${yc} ${x1} ${yb}`;
function setup(api) {
  const P = api.svg;
  // walls: anterior (left), posterior (right), floor
  el.walls = api.el("g", {}, P);
  const W = el.walls;
  el.wA = api.el("rect", {x: 168, y: 300, width: 40, height: 126, rx: 14, fill: "#e9eef1", stroke: "#9fb0b8", "stroke-width": 2.5, filter: "url(#kit-shadow)"}, W);
  el.wP = api.el("rect", {x: 432, y: 300, width: 40, height: 126, rx: 14, fill: "#ead9b6", stroke: "#b9a47a", "stroke-width": 2.5, filter: "url(#kit-shadow)"}, W);
  el.wF = api.el("rect", {x: 168, y: 420, width: 304, height: 32, rx: 14, fill: "#f2e8cf", stroke: "#b9a47a", "stroke-width": 2.5, filter: "url(#kit-shadow)"}, W);
  // lumen
  api.el("rect", {x: 208, y: 262, width: 224, height: 158, rx: 40, fill: "#f6fbfb", stroke: "#c9d6da", "stroke-width": 2.5}, P);
  R.text(api, P, "Inguinal canal", 320, 372, {size: 19, anchor: "middle", color: "#8aa0a8", halo: false});
  // roof: grey base arcs (all four walls look alike at first)
  const dB = ARC(188, 452, 302, 168), dA = ARC(206, 434, 302, 214);
  el.gB = api.el("path", {d: dB, fill: "none", stroke: "#cfd9dd", "stroke-width": 26, "stroke-linecap": "round"}, P);
  el.gA = api.el("path", {d: dA, fill: "none", stroke: "#dbe3e6", "stroke-width": 20, "stroke-linecap": "round"}, P);
  el.roof = api.el("g", {opacity: 0}, P);
  el.glow = api.el("path", {d: dB, fill: "none", stroke: "#ff8a80", "stroke-width": 44, "stroke-linecap": "round", opacity: 0.35, filter: "url(#kit-glow)"}, el.roof);
  el.B = api.el("g", {}, P); el.A = api.el("g", {}, P);
  api.el("path", {d: dB, fill: "none", stroke: "#8e2a27", "stroke-width": 30, "stroke-linecap": "round"}, el.B);
  el.Bp = api.el("path", {d: dB, fill: "none", stroke: "url(#kit-muscle)", "stroke-width": 24, "stroke-linecap": "round"}, el.B);
  api.el("path", {d: dA, fill: "none", stroke: "#a8505a", "stroke-width": 24, "stroke-linecap": "round"}, el.A);
  el.Ap = api.el("path", {d: dA, fill: "none", stroke: "url(#kit-tissue)", "stroke-width": 18, "stroke-linecap": "round"}, el.A);
  [[el.B, dB, 5], [el.A, dA, 4]].forEach(([g, d, w]) => { g.f = api.el("path", {d, fill: "none", stroke: "#fff", "stroke-width": w, "stroke-opacity": 0.55, "stroke-dasharray": "10 7", "stroke-linecap": "round"}, g); });
  // labels
  el.c1 = {};
  el.c1.roof = R.callout(api, P, "Roof", 320, 160, GREY, [320, 196], null);
  el.c1.ant = R.callout(api, P, "Anterior wall", 100, 390, GREY, [170, 380], null);
  el.c1.post = R.callout(api, P, "Posterior wall", 540, 390, GREY, [470, 380], null);
  el.c1.floor = R.callout(api, P, "Floor", 320, 500, GREY, [320, 454], null);
  el.roofRed = R.callout(api, P, "Roof", 320, 160, RED, [320, 196], null);
  el.io = R.callout(api, P, "Internal oblique", 320, 160, RED, [320, 196], null);
  el.ta = R.callout(api, P, "Transversus abdominis", 320, 300, RED, [320, 238], null);
}
function render(t, api) {
  const f = (a, b) => api.seg(t, a, b);
  R.fade(api, el.c1.roof, t, 300, 700, 2300, 2600);
  ["ant", "post", "floor"].forEach((k) => R.fade(api, el.c1[k], t, 400, 800, 2300, 2700));
  // beat 2: other walls dim, roof lights up and arcs draw on
  api.set(el.walls, {opacity: (1 - 0.65 * f(2300, 2800)).toFixed(3)});
  api.set(el.roof, {opacity: f(2500, 3200).toFixed(3)});
  const dim = 1 - 0.65 * f(2300, 2800);
  api.set(el.gB, {opacity: dim.toFixed(3)}); api.set(el.gA, {opacity: dim.toFixed(3)});
  R.drawOn(api, el.B, f(2450, 3500)); R.drawOn(api, el.A, f(2900, 3900));
  [el.B, el.A].forEach((g) => { g.f.setAttribute("stroke-dasharray", "10 7"); g.f.setAttribute("stroke-dashoffset", "0"); });
  R.fade(api, el.roofRed, t, 3400, 3800, 4300, 4600);
  // beat 3: answer chips
  R.fade(api, el.io, t, 4800, 5250);
  R.fade(api, el.ta, t, 5400, 5850);
  const pulse = 0.35 + 0.15 * Math.sin(t / 240);
  api.set(el.glow, {opacity: (t > 4600 ? 0.5 : pulse).toFixed(3)});
}
